<script setup lang="ts">
import {computed} from 'vue';import type{TaskDetail}from './types';import{taskRoute}from './task-route';import{useDispatchStore}from './stores/dispatch';
const props=defineProps<{detail:TaskDetail;sequence:number}>();const store=useDispatchStore();const observed=computed(()=>taskRoute(props.detail,props.sequence,store.snapshot?.map,store.fresh&&!store.demoMode,store.now));
const map=computed(()=>observed.value.route?store.snapshot?.map:null);const route=computed(()=>observed.value.route);const selected=computed(()=>new Set(route.value?.edgeIds??[]));
const bounds=computed(()=>{let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;const add=(p:{x:number;y:number})=>{if(!Number.isFinite(p.x)||!Number.isFinite(p.y))return;minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minY=Math.min(minY,-p.y);maxY=Math.max(maxY,-p.y);};for(const n of map.value?.nodes??[])add(n);for(const e of [...roads.value,...highlighted.value])for(const p of e.points)add(p);for(const r of map.value?.resources??[])if(resources.value.has(r.id))for(const p of r.boundary??[])add(p);if(!Number.isFinite(minX))return'0 0 100 100';const pad=Math.max(1,Math.max(maxX-minX,maxY-minY)*.08);return`${minX-pad} ${minY-pad} ${Math.max(1,maxX-minX)+2*pad} ${Math.max(1,maxY-minY)+2*pad}`;});
function path(points:{x:number;y:number}[]){return points.map((p,i)=>`${i?'L':'M'} ${p.x} ${-p.y}`).join(' ');}
const roads=computed(()=>map.value?.edges.slice(0,3000)??[]);const highlighted=computed(()=>map.value?.edges.filter(e=>selected.value.has(e.id))??[]);const resources=computed(()=>new Set(props.detail.resources?.map(r=>r.resourceId)??[]));
</script>
<template><section class="task-route-map"><h3>原运输路线与当前诊断联动</h3><p>{{observed.reason}}</p><p>当前任务持有资源：{{[...resources].join('、')||'无返回占用'}}。未返回的路线/位置不推测。</p><svg v-if="map&&route" :viewBox="bounds" role="img" aria-label="原命令路线只读地图"><path v-for="e in roads" :key="e.id" :d="path(e.points)" stroke="#53697c" stroke-width="1" vector-effect="non-scaling-stroke" fill="none"/><polygon v-for="r in map.resources.filter(r=>resources.has(r.id)&&r.boundary?.length)" :key="r.id" :points="r.boundary?.map(p=>`${p.x},${-p.y}`).join(' ')" fill="#d395282b" stroke="#d39528" vector-effect="non-scaling-stroke"/><path v-for="e in highlighted" :key="e.id" :d="path(e.points)" stroke="#47e4b3" stroke-width="4" vector-effect="non-scaling-stroke" fill="none"><title>{{e.id}} · {{e.from}} → {{e.to}}</title></path><circle v-for="id in [route.nodeIds[0],route.nodeIds.at(-1)]" :key="id" :cx="map.nodes.find(n=>n.id===id)?.x" :cy="-(map.nodes.find(n=>n.id===id)?.y??0)" r=".2" fill="#ffe27a"><title>{{id}}</title></circle></svg><p v-if="route">业务：{{route.nodeIds.join(' → ')}}<br/>厂家：{{route.vendorSites.join(' → ')}}</p></section></template>
<style scoped>.task-route-map{border:1px solid #334d68;padding:16px;margin:18px 0}.task-route-map p{font-size:12px;line-height:1.8;overflow-wrap:anywhere}.task-route-map svg{width:100%;height:260px;background:#0b1a2e}</style>
